import os, subprocess
def g(d, *a):
    try:
        x = subprocess.run(['git', '-C', d] + list(a), capture_output=True, text=True, timeout=60)
    except subprocess.TimeoutExpired:
        return 'TIMEOUT'
    return x.stdout.strip() if x.returncode == 0 else 'ERR'
def clone(d, rel):
    lr = g(d, 'rev-list', '--left-right', '--count', 'HEAD...refs/remotes/origin/main').split()
    st = g(d, 'status', '--porcelain', '--untracked-files=normal', '--', '.', ':(exclude)conversations')
    dirty = 'TIMEOUT' if st == 'TIMEOUT' else ('?' if st == 'ERR' else len([l for l in st.splitlines() if l.strip()]))
    print('%s/ git HEAD=%s branch=%s ahead=%s behind=%s dirty=%s' % (rel, g(d, 'rev-parse', 'HEAD'), g(d, 'rev-parse', '--abbrev-ref', 'HEAD'),
          lr[0] if len(lr) == 2 else '?', lr[1] if len(lr) == 2 else '?', dirty))
n = [0]
def walk(d, rel, depth):
    for e in sorted(os.listdir(d)):
        if e == 'conversations' or e == '.git':
            continue
        p, r = os.path.join(d, e), rel + '/' + e
        n[0] += 1
        if n[0] > 600:
            return
        if os.path.islink(p):
            print(r, 'link')
        elif os.path.isdir(os.path.join(p, '.git')):
            clone(p, r)
        elif os.path.isdir(p):
            print(r + '/')
            if depth > 1:
                walk(p, r, depth - 1)
        else:
            print(r, 'file')
for name, depth in (('scratch', 2), ('relentless-seeds', 3)):
    d = os.path.realpath(os.path.expanduser('~/rm/' + name))
    if not os.path.isdir(d):
        print(name, d, 'ABSENT')
        continue
    print(name, d)
    walk(d, name, depth)
if n[0] > 600:
    print('... cut at 600 entries')

import calendar, glob, hashlib, json, math, os, re, time
s = os.path.realpath(os.path.expanduser('~/rm/relentless/store'))
ok_ends = ('finish', 'done', 'unhold', 'blocked')
slug = re.compile(r'^[a-z][a-z0-9_]{0,39}$')
idr = re.compile(r'^[A-Za-z0-9_]{1,120}$')
w = lambda v: v if isinstance(v, str) and slug.match(v) else 'other'
num = lambda v: v if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) else 0
def e(t):
    try:
        return calendar.timegm(time.strptime(str(t)[:19], '%Y-%m-%dT%H:%M:%S'))
    except (ValueError, TypeError):
        return None
def j(p):
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except (OSError, ValueError):
        return None
now = time.time()
print('store %s read_at=%s' % (s, time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(now))))
try:
    names = sorted(os.listdir(os.path.join(s, 'items')))
except OSError as x:
    print('NO_STORE', str(x)[:120])
    raise SystemExit(0)
byh, started, failed, rows, stat = {}, {}, {}, [], {}
names = [n for n in names if idr.match(n)]
for n in names:
    byh[hashlib.sha1(n.encode()).hexdigest()[:10]] = n
    st = j(os.path.join(s, 'items', n, 'state.json'))
    st = st if isinstance(st, dict) else {}
    ends = {}
    try:
        with open(os.path.join(s, 'items', n, 'attempts.jsonl'), encoding='utf-8') as f:
            for ln in f:
                try:
                    r = json.loads(ln)
                except ValueError:
                    continue
                if not isinstance(r, dict) or not isinstance(r.get('gen'), int):
                    continue
                if r.get('start'):
                    started[(n, r['gen'])] = e(r.get('at'))
                elif r.get('end') and 'kind' not in r:
                    k = w(r['end'])
                    ends[k] = ends.get(k, 0) + 1
                    if k not in ok_ends:
                        failed[(n, r['gen'])] = k
    except OSError:
        pass
    sts = w(st.get('status'))
    stat[sts] = stat.get(sts, 0) + 1
    rows.append((-num(st.get('spent')), n, sts, st.get('gen') if isinstance(st.get('gen'), int) else '-', num(st.get('returns')), num(st.get('spent')), ends))
print('items %d by_status %s' % (len(names), ' '.join('%s=%d' % kv for kv in sorted(stat.items()))))
day = {}
for p in sorted(glob.glob(os.path.join(s, 'spend-*.json'))):
    sp = j(p)
    runs = sp.get('runs') if isinstance(sp, dict) else None
    if not isinstance(runs, dict):
        print('spend %s UNREADABLE' % re.sub(r'[^\w.-]', '_', os.path.basename(p))[:40])
        continue
    d = os.path.basename(p)[6:14]
    if not d.isdigit():
        continue
    day[d] = runs
    print('spend %s spent=%d runs=%d' % (d, num(sp.get('spent')), len(runs)))
rx = re.compile(r'rm-relentless-(work|check)-([0-9a-f]{10})-g(\d+)')
for hours in (24, 72):
    lo = now - hours * 3600.0
    d0 = time.strftime('%Y%m%d', time.gmtime(lo))
    tot = ret = unm = 0
    be = {}
    for d, runs in sorted(day.items()):
        if d < d0:
            continue
        for m, tk in runs.items():
            tk = num(tk)
            if not tk:
                continue
            g = rx.match(m)
            key = (byh.get(g.group(2)), int(g.group(3))) if g else None
            t = started.get(key) if key else None
            if t is None:
                unm += tk
                continue
            if not lo <= t <= now + 300:
                continue
            tot += tk
            if key in failed:
                ret += tk
                k = '%s/%s' % (failed[key], g.group(1))
                be[k] = be.get(k, 0) + tk
    print('returned window_h=%d total=%d returned=%d pct=%.1f unmapped=%d' % (hours, tot, ret, 100.0 * ret / tot if tot else 0, unm))
    for k, v in sorted(be.items(), key=lambda kv: (-kv[1], kv[0]))[:12]:
        print('  by_end %s tokens=%d pct=%.1f' % (k, v, 100.0 * v / tot if tot else 0))
rows.sort()
out, more = 0, 0
for _, n, sts, gen, rets, sp, ends in rows:
    ln = 'item %s h=%s status=%s gen=%s returns=%s spent=%s ends=%s' % (n, hashlib.sha1(n.encode()).hexdigest()[:10], sts, gen, rets, sp, ','.join('%s:%d' % kv for kv in sorted(ends.items())) or '-')
    if out + len(ln) > 14000:
        more += 1
        continue
    out += len(ln) + 1
    print(ln)
if more:
    print('... %d more items (smaller spent)' % more)

import json, os, re, sys
item = sys.argv[1] if len(sys.argv) > 1 else ''
if not re.match(r'^[A-Z][A-Z0-9_]{1,120}$', item):
    print('refused: no item id'); sys.exit(2)
d = os.path.realpath(os.path.expanduser('~/rm/relentless/live'))
left = [18000]
def say(s):
    s = str(s)
    if left[0] > 0:
        print(s[:left[0]]); left[0] -= len(s) + 1
say('live-round evidence for %s in %s' % (item, d))
if not os.path.isdir(d):
    say('no live folder'); sys.exit(1)
crit = os.path.join(d, item + '.criteria')
if os.path.isfile(crit):
    say('== %s.criteria' % item)
    say(open(crit, encoding='utf-8', errors='replace').read()[:2000].rstrip())
runs = []
try:
    with open(os.path.join(d, 'runs.jsonl'), encoding='utf-8', errors='replace') as f:
        for ln in f:
            if item not in ln:
                continue
            try:
                x = json.loads(ln)
            except ValueError:
                continue
            if isinstance(x, dict) and x.get('item') == item:
                runs.append(x)
except OSError:
    pass
say('== runs.jsonl: %d run(s) of %s, newest last' % (len(runs), item))
for x in runs[-12:]:
    say('run at=%s criterion=%s level=%s outcome=%s sha=%s proof_exit=%s log=%s why=%s' % (
        x.get('at'), x.get('criterion'), x.get('level'), x.get('outcome'), str(x.get('sha'))[:12], x.get('proof_exit'),
        os.path.basename(str(x.get('log') or '')), str(x.get('why') or '')[:200]))
logs = sorted((n for n in os.listdir(d) if n.startswith(item + '-') and n.endswith('.log')), reverse=True)
say('== %d log(s); newest first, head 3 and tail 25 lines each' % len(logs))
for n in logs[:8]:
    try:
        t = open(os.path.join(d, n), encoding='utf-8', errors='replace').read().splitlines()
    except OSError:
        continue
    say('--- %s (%d lines)' % (n, len(t)))
    for ln in (t[:3] + ['...'] + t[-25:]) if len(t) > 28 else t:
        say('  ' + ln[:300])

import os
